SELECT p.Id,p.MimeType,p.SeoFilename,p.AltAttribute,p.TitleAttribute,p.VirtualPath FROM Picture p WHERE EXISTS(SELECT 1 FROM Product_Picture_Mapping m WHERE m.PictureId=p.Id AND m.ProductId IN (SELECT p.Id FROM Product p WHERE p.Published=1 AND p.Deleted=0 AND p.DisableBuyButton=0 AND p.CallForPrice=0 AND p.VisibleIndividually=1 AND EXISTS(SELECT 1 FROM ProductAttributeCombination pac WHERE pac.ProductId=p.Id AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0))) OR EXISTS(SELECT 1 FROM ProductAttributeCombination v WHERE v.PictureId=p.Id AND v.ProductId IN (SELECT p.Id FROM Product p WHERE p.Published=1 AND p.Deleted=0 AND p.DisableBuyButton=0 AND p.CallForPrice=0 AND p.VisibleIndividually=1 AND EXISTS(SELECT 1 FROM ProductAttributeCombination pac WHERE pac.ProductId=p.Id AND pac.Deleted=0 AND pac.IsNotExist=0 AND pac.StockAvailabilityTypeId=20 AND pac.StockQuantity>0 AND pac.FinalPrice>0))) OR EXISTS(SELECT 1 FROM Category c WHERE c.PictureId=p.Id AND c.Deleted=0) OR EXISTS(SELECT 1 FROM Manufacturer b WHERE b.PictureId=p.Id AND b.Deleted=0) OR EXISTS(SELECT 1 FROM HomePageSectionItem h WHERE (h.PictureId=p.Id OR h.MobilePictureId=p.Id) AND h.Published=1 AND h.Deleted=0)
